UPDATE public.stories 
SET 
    content_ko = '작년 가을에 서울에 도착했어요. 날씨가 선선하면서도 햇살이 따뜻해서 산책하기 정말 좋았습니다. 하늘은 특히 맑고 파랗고, 단풍이 곱게 물든 공원을 걷는 건 마치 그림 속을 거니는 기분이었어요. 경복궁에서는 한복을 빌려 입고 사진을 찍었는데, 전통 문양이 예뻤습니다. 그런데 가장 기억에 남는 건 길거리에서 산 호두과자와 고구마였어요. 아직도 그 달콤하고 따뜻한 맛이 입안에 남아 있어서, 매년 가을이 오면 또 그리워집니다.',
    content_id = 'Saya tiba di Seoul musim gugur lalu. Cuacanya sejuk namun sinar matahari terasa hangat, sehingga sangat menyenangkan untuk berjalan-jalan. Langit terutama sangat cerah dan biru, dan berjalan di taman yang daunnya berubah warna menjadi merah kecokelatan terasa seperti berada di dalam lukisan. Di Istana Gyeongbokgung, saya menyewa hanbok dan berfoto—motif tradisionalnya sangat indah. Namun, yang paling tak terlupakan adalah kacang kenari panggang dan ubi jalar yang saya beli dari pedagang kaki lima. Rasanya yang manis dan hangat masih terngiang di lidah saya hingga kini, sehingga setiap kali musim gugur tiba, saya selalu merindukannya lagi.',
    content_en = 'I arrived in Seoul last autumn. The weather was cool yet sunny and warm, making it truly delightful for strolling. The sky was especially clear and blue, and walking through the park with its beautifully colored autumn foliage felt like wandering through a painting. At Gyeongbokgung Palace, I rented a hanbok and took photos—the traditional patterns were exquisite. Yet what remains most memorable are the roasted walnuts and sweet potatoes I bought from a street vendor. Their sweet, warm taste still lingers in my mouth, so every autumn I find myself yearning for them again.',
