":" "},{"t":"따뜻한","l":"따뜻하다"},{"t":" ","l":" "},{"t":"맛이","l":"맛"},{"t":" ","l":" "},{"t":"입안에","l":"입안"},{"t":" ","l":" "},{"t":"남아","l":"남다"},{"t":" ","l":" "},{"t":"있어서","l":"있다"},{"t":",","l":","},{"t":" ","l":" "},{"t":"매년","l":"매년"},{"t":" ","l":" "},{"t":"가을이","l":"가을"},{"t":" ","l":" "},{"t":"오면","l":"오다"},{"t":" ","l":" "},{"t":"또","l":"또"},{"t":" ","l":" "},{"t":"그리워집니다","l":"그리워지다"}]'::jsonb
