UPDATE public.stories 
SET 
    content_ko = '한국은 사계절이 뚜렷한 나라로, 각 계절마다 독특한 매력이 있습니다. 봄에는 벚꽃이 만개하면서 날씨가 따뜻해지지만, 때때로 바람이 차갑기도 합니다. 여름은 덥고 습하기 때문에 에어컨이 필수적이며, 장마철에는 비가 자주 오기 때문에 우산을 챙기는 게 좋습니다. 가을은 단풍이 아름답고 하늘이 높아 산책하기에 딱 좋은데, 낮과 밤의 기온 차가 크기 때문에 얇은 외투를 준비해야 합니다. 겨울은 눈이 많이 오고 매우 추워서 두꺼운 옷을 입어야 하며, 한국 사람들은 계절에 따라 음식과 활동을 다양하게 즐깁니다.',
    content_id = 'Korea adalah negara dengan empat musim yang sangat jelas, masing-masing musim memiliki daya tarik uniknya sendiri. Pada musim semi, bunga sakura mekar indah dan cuaca menjadi lebih hangat, meskipun kadang-kadang angin masih terasa dingin. Musim panas cukup panas dan lembap, sehingga penggunaan pendingin ruangan menjadi keharusan; selama musim hujan, hujan sering turun, jadi disarankan membawa payung. Musim gugur menawarkan pemandangan daun berwarna-warni yang memukau dan langit yang cerah serta tinggi—waktu yang sempurna untuk berjalan kaki—namun perbedaan suhu antara siang dan malam cukup signifikan, sehingga disarankan membawa jaket tipis. Musim dingin ditandai dengan banyak salju dan cuaca yang sangat dingin, sehingga pakaian tebal wajib dikenakan; masyarakat Korea juga menikmati beragam makanan dan aktivitas sesuai dengan perubahan musim.',
    content_en = 'South Korea is a country with four distinct seasons, each offering its own unique charm. In spring, cherry blossoms bloom beautifully and the weather grows warmer, though it can still be chilly at times. Summer is hot and humid, making air conditioning essential; during the rainy season, frequent rainfall makes carrying an umbrella advisable. Autumn boasts stunning foliage and clear, high skies—ideal for leisurely walks—but the large temperature difference between day and night means a light jacket is recommended. Winter brings heavy snowfall and bitterly cold temperatures, requiring thick clothing; Koreans also enjoy a wide variety of seasonal foods and activities.',
    content_tokens = '[{"t":"한국은","l":"한국"},{"t":" ","l":" "},{"t":"사계절이","l":"사계절"},{"t":" ","l":" "},{"t":"뚜렷한","l":"뚜렷하다"},{"t":" ","l":" "},{"t":"나라로","l":"나라"},{"t":",","l":","},{"t":" ","l":" "},{"t":"각","l":"각"},{"t":" ","l":" "},{"t":"계절마다","l":"계절"},{"t":" ","l":" "},{"t":"독특한","l":"독특하다"},{"t":" ","l":" "},{"t":"매력이","l":"매력"},{"t":" ","l":" "},{"t":"있습니다","l":"있다"},{"t":".","l":"."},{"t":"\n","l":"\n"},{"t":"봄에는","l":"봄"},{"t":" ","l":" "},{"t":"벚꽃이","l":"벚꽃"},{"t":" ","l":" "},{"t":"만개하면서","l":"만개하다"},{"t":" ","l":" "},{"t":"날씨가","l":"날씨"},{"t":" ","l":" "},{"t":"따뜻해지지만","l":"따뜻해지다"},{"t":",","l":","},{"t":" ","l":" "},{"t":"때때로","l":"때때로"},{"t":" ","l":" "},{"t":"바람이","l":"바람"},{"t":" ","l":" "},{"t":"차갑기도","l":"차갑다"},{"t":" ","l":" "},{"t":"합니다","l":"하다"},{"t":".","l":"."},{"t":"\n","l":"\n"},{"t":"여름은","l":"여름"},{"t":" ","l":" "},{"t":"덥고","l":"덥다"},{"t":" ","l":" "},{"t":"습하기","l":"습하다"},{"t":" ","l":" "},{"t":"때문에","l":"때문이다"},{"t":" ","l":" "},{"t":"에어컨이","l":"에어컨"},{"t":" ","l":" "},{"t":"필수적이며","l":"필수적이다"},{"t":",","l":","},{"t":" ","l":" "},{"t":"장마철에는","l":"장마철"},{"t":" ","l":" "},{"t":"비가","l":"비"},{"t":" ","l":" "},{"t":"자주","l":"자주"},{"t":" ","l":" "},{"t":"오기","l":"오다"},{"t":" ","l":" "},{"t":"때문에","l":"때문이다"},{"t":" ","l":" "},{"t":"우산을","l":"우산"},{"t":" ","l":" "},{"t":"챙기는","l":"챙기다"},{"t":" ","l":" "},{"t":"게","l":"게"},{"t":" ","l":" "},{"t":"좋습니다","l":"좋다"},{"t":".","l":"."},{"t":"\n","l":"\n"},{"t":"가을은","l":"가을"},{"t":" ","l":" "},{"t":"단풍이","l":"단풍"},{"t":" ","l":" "},{"t":"아름답고","l":"아름답다"},{"t":" ","l":" "},{"t":"하늘이","l":"하늘"},{"t":" ","l":" "},{"t":"높아","l":"높다"},{"t":" ","l":" "},{"t":"산책하기에","l":"산책하다"},{"t":" ","l":" "},{"t":"딱","l":"딱"},{"t":" ","l":" "},{"t":"좋은데","l":"좋다"},{"t":",","l":","},{"t":" ","l":" "},{"t":"낮과","l":"낮"},{"t":" ","l":" "},{"t":"밤의","l":"밤"},{"t":" ","l":" "},{"t":"기온","l":"기온"},{"t":" ","l":" "},{"t":"차가","l":"차이다"},{"t":" ","l":" "},{"t":"크기","l":"크다"},{"t":" ","l":" "},{"t":"때문에","l":"때문이다"},{"t":