UPDATE public.stories 
SET 
    content_ko = '한국의 대중교통은 매우 편리하지만, 처음 이용할 때는 약간 혼란스러울 수도 있어요. 지하철은 서울 전역을 연결하면서도 정확한 시간에 운행되기 때문에 믿을 수 있고, 버스는 노선이 다양하고 자주 오기 때문에 이동이 자유로워요. 특히 교통카드 하나로 지하철과 버스를 모두 탈 수 있어서 환승도 간편해요. 택시는 다른 나라에 비해 요금이 저렴한 편인데, 앱으로 부르면 더 편리하고 안전하답니다. 따라서 한국에서 생활하거나 여행할 때는 대중교통을 적극 활용하는 게 정말 좋아요.',
    content_id = 'Transportasi umum di Korea sangat nyaman, namun mungkin terasa sedikit membingungkan saat pertama kali menggunakannya. Kereta bawah tanah terpercaya karena beroperasi tepat waktu dan menghubungkan seluruh wilayah Seoul, sementara bus menawarkan beragam rute dan frekuensi kedatangan yang tinggi sehingga memudahkan mobilitas. Terlebih lagi, Anda bisa menggunakan satu kartu transportasi untuk naik kereta bawah tanah maupun bus, sehingga proses pindah moda menjadi sangat praktis. Taksi di Korea relatif lebih murah dibandingkan negara lain, dan memesannya melalui aplikasi membuatnya lebih mudah serta aman. Oleh karena itu, memanfaatkan transportasi umum secara aktif sangat direkomendasikan ketika tinggal atau berwisata di Korea.',
    content_en = 'Public transportation in Korea is highly convenient, though it may feel slightly confusing at first use. The subway is reliable, running on precise schedules while connecting all areas of Seoul, and buses offer diverse routes and frequent arrivals, making travel flexible. Moreover, a single transit card can be used for both subways and buses, simplifying transfers. Taxis are relatively inexpensive compared to those in other countries, and booking them via apps makes the process even more convenient and safer. Therefore, actively using public transportation is highly recommended when living in or traveling around Korea.',
    content_tokens = '[{"t":"한국의","l":"한국"},{"t":" ","l":" "},{"t":"대중교통은","l":"대중교통"},{"t":" ","l":" "},{"t":"매우","l":"매우"},{"t":" ","l":" "},{"t":"편리하지만","l":"편리하다"},{"t":",","l":","},{"t":" ","l":" "},{"t":"처음","l":"처음"},{"t":" ","l":" "},{"t":"이용할","l":"이용하다"},{"t":" ","l":" "},{"t":"때는","l":"때"},{"t":" ","l":" "},{"t":"약간","l":"약간"},{"t":" ","l":" "},{"t":"혼란스러울","l":"혼란스럽다"},{"t":" ","l":" "},{"t":"수도","l":"수도"},{"t":" ","l":" "},{"t":"있어요","l":"있다"},{"t":".","l":"."},{"t":"\n","l":"\n"},{"t":"지하철은","l":"지하철"},{"t":" ","l":" "},{"t":"서울","l":"서울"},{"t":" ","l":" "},{"t":"전역을","l":"전역"},{"t":" ","l":" "},{"t":"연결하면서도","l":"연결하다"},{"t":" ","l":" "},{"t":"정확한","l":"정확하다"},{"t":" ","l":" "},{"t":"시간에","l":"시간"},{"t":" ","l":" "},{"t":"운행되기","l":"운행하다"},{"t":" ","l":" "},{"t":"때문에","l":"때문"},{"t":" ","l":" "},{"t":"믿을","l":"믿다"},{"t":" ","l":" "},{"t":"수","l":"수"},{"t":" ","l":" "},{"t":"있고","l":"있다"},{"t":",","l":","},{"t":" ","l":" "},{"t":"버스는","l":"버스"},{"t":" ","l":" "},{"t":"노선이","l":"노선"},{"t":" ","l":" "},{"t":"다양하고","l":"다양하다"},{"t":" ","l":" "},{"t":"자주","l":"자주"},{"t":" ","l":" "},{"t":"오기","l":"오다"},{"t":" ","l":" "},{"t":"때문에","l":"때문"},{"t":" ","l":" "},{"t":"이동이","l":"이동"},{"t":" ","l":" "},{"t":"자유로워요","l":"자유롭다"},{"t":".","l":"."},{"t":"\n","l":"\n"},{"t":"특히","l":"특히"},{"t":" ","l":" "},{"t":"교통카드","l":"교통카드"},{"t":" ","l":" "},{"t":"하나로","l":"하나"},{"t":" ","l":" "},{"t":"지하철과","l":"지하철"},{"t":" ","l":" "},{"t":"버스를","l":"버스"},{"t":" ","l":" "},{"t":"모두","l":"모두"},{"t":" ","l":" "},{"t":"탈","l":"타다"},{"t":" ","l":" "},{"t":"수","l":"수"},{"t":" ","l":" "},{"t":"있어서","l":"있다"},{"t":" ","l":" "},{"t":"환승도","l":"환승"},{"t":" ","l":" "},{"t":"간편해요","l":"간편하다"},{"t":".","l":"."},{"t":"\n","l":"\n"},{"t":"택시는","l":"택시"},{"t":" ","l":" "},{"t":"다른","l":"다르다"},{"t":" ","l":" "},{"t":"나라에","l":"나라"},{"t":" ","l":" "},{"t":"비해","l":"비하다"},{"t":" ","l":" "},{"t":"요금이","l":"요금"},{"t":" ","l":" "},{"t":"저렴한","l":"저렴하다"},{"t":" ","l":" "},{"t":"편인데","l":"편"},{"t":